/**
 * The measurement, written down.
 *
 * Every cell here was produced by `runs.ts` — two injection layers, six
 * wirings, nine faults, each cell a series of three real calls — and
 * `runs.test.ts` produces them all again on every `pnpm test` and fails if any
 * cell has moved. Nothing in this file is computed from the thing it describes,
 * which is the only reason it is worth reading: a table generated by the code
 * it scores agrees with it by construction.
 *
 * `README.md` renders these cells and `readme.test.ts` checks that it renders
 * *these* cells, so the document cannot drift from the table and the table
 * cannot drift from the runs.
 *
 * ---------------------------------------------------------------------------
 * Reading a cell
 * ---------------------------------------------------------------------------
 * `outcome/band/requests`:
 *
 *   - **outcome** — what the last call in the series did (`outcomes.ts`).
 *   - **band** — whether that call settled before the injected fault could
 *     have elapsed, only after enduring it, or not at all.
 *   - **requests** — how many requests the whole three-call series made. This
 *     is the column the retry and breaker rows live in: both of them can be
 *     completely inert and still return exactly what the row above returns.
 *
 * The encoding is a string parsed by `row` rather than three fields per cell,
 * because a 54-cell table has to be legible as a table. The parser is strict —
 * an outcome or band that is not in the vocabulary throws at module load — so
 * the compactness costs nothing in safety.
 */

import { FAULT_IDS, type FaultId } from './faults.ts'
import { LAYER_IDS, type LayerId } from './layers.ts'
import { BANDS, type Band, type Cell, OUTCOMES, type Outcome, type Table } from './outcomes.ts'
import { POLICY_IDS, type PolicyId } from './policies.ts'

const isOutcome = (value: string): value is Outcome => (OUTCOMES as readonly string[]).includes(value)

const isBand = (value: string): value is Band => (BANDS as readonly string[]).includes(value)

function cell(encoded: string): Cell {
  const [outcome, band, requests] = encoded.split('/')

  if (outcome === undefined || !isOutcome(outcome)) {
    throw new Error(`not an outcome: ${encoded}`)
  }

  if (band === undefined || !isBand(band)) {
    throw new Error(`not a band: ${encoded}`)
  }

  const count = Number(requests)

  if (!Number.isInteger(count) || count < 1) {
    throw new Error(`not a request count: ${encoded}`)
  }

  return { outcome, band, requests: count }
}

/** One policy's row, in the column order of `FAULT_IDS`. */
function row(...encoded: readonly string[]): Readonly<Record<FaultId, Cell>> {
  if (encoded.length !== FAULT_IDS.length) {
    throw new Error(`a row needs ${String(FAULT_IDS.length)} cells, got ${String(encoded.length)}`)
  }

  return Object.fromEntries(
    FAULT_IDS.map((fault, index) => [fault, cell(encoded[index] ?? '')]),
  ) as Readonly<Record<FaultId, Cell>>
}

/**
 * The two tables: what each wiring does to each fault, at each layer.
 *
 * `socket` is the ground truth and `fetch-stub` is the cheap imitation of it.
 * Read them side by side — the twelve cells where they disagree are the second
 * half of this directory, and every one of those twelve is a cell where the
 * imitation says the *opposite* of the truth.
 */
export const TABLES: Readonly<Record<LayerId, Table>> = {
  socket: {
    bare: row('ok/prompt/3', 'ok/waited-out/3', 'ok/waited-out/3', 'wrong-body/prompt/3', 'wrong-body/prompt/3', 'malformed/prompt/3', 'refused/prompt/3', 'reset/prompt/3', 'hung/deadline/3'),
    'race-timeout': row('ok/prompt/3', 'aborted/prompt/3', 'ok/waited-out/3', 'http-error/prompt/3', 'http-error/prompt/3', 'malformed/prompt/3', 'refused/prompt/3', 'reset/prompt/3', 'aborted/prompt/3'),
    'signal-timeout': row('ok/prompt/3', 'aborted/prompt/3', 'aborted/prompt/3', 'http-error/prompt/3', 'http-error/prompt/3', 'malformed/prompt/3', 'refused/prompt/3', 'reset/prompt/3', 'aborted/prompt/3'),
    'retry-5xx': row('ok/prompt/3', 'aborted/prompt/3', 'aborted/prompt/3', 'http-error/prompt/9', 'ok/prompt/6', 'malformed/prompt/3', 'refused/prompt/3', 'reset/prompt/3', 'aborted/prompt/3'),
    'retry-any': row('ok/prompt/3', 'aborted/prompt/9', 'aborted/prompt/9', 'http-error/prompt/9', 'ok/prompt/6', 'malformed/prompt/9', 'refused/prompt/9', 'reset/prompt/9', 'aborted/prompt/9'),
    breaker: row('ok/prompt/3', 'breaker-open/prompt/2', 'breaker-open/prompt/2', 'breaker-open/prompt/2', 'ok/prompt/6', 'breaker-open/prompt/2', 'breaker-open/prompt/2', 'breaker-open/prompt/2', 'breaker-open/prompt/2'),
  },
  'fetch-stub': {
    bare: row('ok/prompt/3', 'ok/waited-out/3', 'ok/waited-out/3', 'wrong-body/prompt/3', 'wrong-body/prompt/3', 'malformed/prompt/3', 'refused/prompt/3', 'reset/prompt/3', 'hung/deadline/3'),
    'race-timeout': row('ok/prompt/3', 'aborted/prompt/3', 'ok/waited-out/3', 'http-error/prompt/3', 'http-error/prompt/3', 'malformed/prompt/3', 'refused/prompt/3', 'reset/prompt/3', 'aborted/prompt/3'),
    'signal-timeout': row('ok/prompt/3', 'ok/waited-out/3', 'ok/waited-out/3', 'http-error/prompt/3', 'http-error/prompt/3', 'malformed/prompt/3', 'refused/prompt/3', 'reset/prompt/3', 'hung/deadline/3'),
    'retry-5xx': row('ok/prompt/3', 'ok/waited-out/3', 'ok/waited-out/3', 'http-error/prompt/9', 'ok/prompt/6', 'malformed/prompt/3', 'refused/prompt/3', 'reset/prompt/3', 'hung/deadline/3'),
    'retry-any': row('ok/prompt/3', 'ok/waited-out/3', 'ok/waited-out/3', 'http-error/prompt/9', 'ok/prompt/6', 'malformed/prompt/9', 'refused/prompt/9', 'reset/prompt/9', 'hung/deadline/3'),
    breaker: row('ok/prompt/3', 'ok/waited-out/3', 'ok/waited-out/3', 'breaker-open/prompt/2', 'ok/prompt/6', 'breaker-open/prompt/2', 'breaker-open/prompt/2', 'breaker-open/prompt/2', 'hung/deadline/3'),
  },
}

/**
 * What the origin counted, per fault, over the whole `socket` layer.
 *
 * The independent witness. The `requests` column of every cell above is
 * counted by the harness, which wraps the transport — so a wrapper that
 * miscounted would agree with itself perfectly. This is the same quantity read
 * off the server that received the requests, and `runs.test.ts` requires the
 * two to agree fault by fault.
 *
 * `connection-refused` is 0 and must be: it is measured against a port that
 * was bound and closed, so a non-zero count here would mean the runs reached
 * the live origin and the whole column is measuring the wrong thing.
 */
export const ORIGIN_HITS: Readonly<Record<FaultId, number>> = {
  healthy: 18,
  'slow-headers': 23,
  'slow-body': 23,
  'error-500': 29,
  'transient-500': 27,
  'malformed-body': 23,
  'connection-refused': 0,
  'reset-mid-body': 23,
  'black-hole': 23,
}

/** Cells in one table. */
export const CELLS_PER_TABLE = POLICY_IDS.length * FAULT_IDS.length

/** Cells the suite re-derives on every run. */
export const TOTAL_CELLS = CELLS_PER_TABLE * LAYER_IDS.length

export const cellAt = (layer: LayerId, policy: PolicyId, fault: FaultId): Cell =>
  TABLES[layer][policy][fault]

/** Requests the `socket` layer's cells say were made, for one fault. */
export const harnessRequests = (fault: FaultId): number =>
  POLICY_IDS.reduce((total, policy) => total + cellAt('socket', policy, fault).requests, 0)
